"""Build the static Science catalog from its public-facing case descriptions."""

import argparse
from html import escape
import json
from pathlib import Path
import re


ROOT = Path(__file__).resolve().parents[1]
BRAND = 'SimulationLE <span class="brand-slash">/</span> Science'
ENGINEER = 'https://huayuankou333.github.io/omniale/simulationle-engineer/'


def page(title, description, body, prefix=""):
    home = prefix or "./"
    return f'''<!doctype html>
<!-- Generated by scripts/build_catalog.py. Edit content/cases.json or the template. -->
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="description" content="{escape(description)}">
  <meta name="theme-color" content="#f8f7f3">
  <title>{escape(title)}</title>
  <link rel="icon" href="{prefix}assets/favicon.png">
  <link rel="stylesheet" href="{prefix}assets/style.css">
  <script type="module" src="{prefix}assets/site.js"></script>
</head>
<body>
  <a class="skip" href="#main">跳到正文</a>
  <header class="site-header">
    <div class="wrap header-inner">
      <a class="brand" href="{home}"><span class="brand-mark" aria-hidden="true"></span><span>{BRAND}</span></a>
      <nav aria-label="主导航"><a href="{prefix}#cases">案例档案</a><a class="nav-external" href="{ENGINEER}">Engineer <span aria-hidden="true">↗</span></a></nav>
    </div>
  </header>
{body}
</body>
</html>
'''


def card(case):
    key, domain = map(escape, case["domain"])
    slug, plot, title = (escape(case[key]) for key in ("slug", "plot", "title"))
    return f'''          <article class="case-card" data-domain="{key}" data-keywords="{escape(case['keywords'])}">
            <a class="case-link" href="cases/{slug}/" aria-labelledby="case-{plot}">
              <div class="card-body">
                <p class="case-meta"><strong>{domain}</strong> <span>{escape(case['software'])}</span></p>
                <h2 id="case-{plot}">{title}</h2>
                <p class="case-question">{escape(case['cardQuestion'])}</p>
              </div>
              <div class="card-visual theme-{plot}"><canvas data-plot="{plot}-card" role="img" aria-label="{escape(case['coverAlt'])}"></canvas></div>
              <p class="case-output"><strong>预期交付</strong> {escape(case['cardOutput'])}</p>
            </a>
          </article>'''


def index(cases):
    domains = dict(case["domain"] for case in cases)
    filters = '\n'.join(
        f'          <button type="button" data-filter="{escape(key)}" aria-pressed="false">{escape(label)}</button>'
        for key, label in domains.items()
    )
    cards = '\n'.join(map(card, cases))
    body = f'''  <main id="main">
    <section id="cases" class="case-section" aria-labelledby="archive-title">
      <div class="wrap">
        <div class="section-head">
          <h1 id="archive-title">{BRAND}</h1>
          <label class="search"><span class="search-icon" aria-hidden="true"></span><input type="search" id="case-search" placeholder="搜索案例" aria-label="搜索案例、软件或领域"></label>
        </div>
        <div class="filters" role="group" aria-label="按领域筛选">
          <button type="button" data-filter="all" aria-pressed="true">全部</button>
{filters}
          <span class="sr-only" id="case-count" role="status">{len(cases)} 个案例</span>
        </div>
        <div class="case-grid">
{cards}
        </div>
        <p class="case-note" id="case-note">封面均为示意图</p>
        <div class="empty-state" id="empty-state" hidden><p>没有匹配的案例。</p><button type="button" id="reset-search">清除搜索与筛选</button></div>
      </div>
    </section>
  </main>'''
    return page("SimulationLE / Science", f"浏览 {len(cases)} 个科学研究案例的任务、输入和预期交付。", body)


def descriptions(pairs):
    return '\n'.join(
        f'        <div><dt>{escape(label)}</dt><dd>{escape(value)}</dd></div>'
        for label, value in pairs
    )


def detail(case, next_case):
    title, question, plot = (escape(case[key]) for key in ("title", "question", "plot"))
    software = escape(case["software"])
    if "softwareUrl" in case:
        software = f'<a href="{escape(case["softwareUrl"])}">{software}</a>'
    brief = descriptions(zip(("给定输入", "要做的事", "预期交付"), case["brief"]))
    steps = '\n'.join(
        f'        <li><strong>{escape(label)}</strong><p>{escape(value)}</p></li>'
        for label, value in case["steps"]
    )
    sources = ' · '.join(f'<a href="{escape(url)}">{escape(label)}</a>' for label, url in case.get("sources", []))
    if sources:
        sources = f'      <p class="case-scope">{sources}</p>\n'
    caption = escape(case["figureModes"][0][1])
    controls = '\n'.join(
        f'          <button type="button" data-mode="{mode}" data-note="{escape(note)}" aria-pressed="{pressed}">{escape(label)}</button>'
        for (mode, pressed), (label, note) in zip((("default", "true"), ("alternative", "false")), case["figureModes"])
    )
    outputs = '\n'.join(
        f'        <tr><th scope="row">{escape(label)}</th><td>{escape(value)}</td></tr>'
        for label, value in case["outputs"]
    )
    body = f'''  <main id="main" class="detail">
    <p class="breadcrumb"><a href="../../#cases">案例档案</a><span aria-hidden="true">/</span>{escape(case['domain'][1])}</p>
    <header class="detail-header">
      <h1>{title}</h1>
      <p class="detail-question">{question}</p>
      <p class="detail-software">{software}</p>
    </header>
    <dl class="case-brief" aria-label="任务概览">
{brief}
    </dl>
    <nav class="case-nav" aria-label="本页目录"><a href="#task">任务拆解</a><a href="#inputs">输入与来源</a><a href="#figure">图示</a><a href="#outputs">预期交付</a></nav>
    <section class="case-block" id="task">
      <h2>{escape(case['taskTitle'])}</h2>
      <p class="case-intro">{escape(case['taskIntro'])}</p>
      <ol class="task-steps">
{steps}
      </ol>
    </section>
    <section class="case-block" id="inputs">
      <h2>输入与来源</h2>
      <dl class="resource-list">
{descriptions(case['inputs'])}
      </dl>
{sources}    </section>
    <figure class="detail-figure theme-{plot}" id="figure">
      <div class="figure-toolbar">
        <h2>{escape(case['figureTitle'])}</h2>
        <div class="figure-controls" role="group" aria-label="切换示意图">
{controls}
        </div>
      </div>
      <canvas data-plot="{plot}-detail" role="img" aria-label="{caption}"></canvas>
      <figcaption aria-live="polite">{caption}</figcaption>
    </figure>
    <section class="case-block" id="outputs">
      <h2>预期交付</h2>
      <table class="deliverable-table" aria-label="预期交付">
        <thead><tr><th scope="col">产物</th><th scope="col">用途</th></tr></thead>
        <tbody>
{outputs}
        </tbody>
      </table>
      <p class="case-scope"><strong>适用范围</strong>{escape(case['scope'])}</p>
    </section>
  </main>
  <footer class="site-footer"><div class="wrap footer-inner"><a href="../../#cases">返回案例档案</a><a href="../{escape(next_case['slug'])}/">下一案例 · {escape(next_case['title'])}</a></div></footer>'''
    return page(f"{case['title']} · SimulationLE / Science", case["cardQuestion"], body, "../../")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Verify that the generated pages are current.")
    options = parser.parse_args()
    cases = json.loads((ROOT / "content/cases.json").read_text(encoding="utf-8"))
    slugs = [case["slug"] for case in cases]
    if len(set(slugs)) != len(slugs) or not all(re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", slug) for slug in slugs):
        raise SystemExit("Case slugs must be unique and use lowercase letters, digits, and hyphens.")
    pages = {ROOT / "index.html": index(cases)}
    for position, case in enumerate(cases):
        path = ROOT / "cases" / case["slug"] / "index.html"
        pages[path] = detail(case, cases[(position + 1) % len(cases)])
    for path, content in pages.items():
        if options.check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                raise SystemExit(f"Regenerate {path.relative_to(ROOT)} with scripts/build_catalog.py")
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")


if __name__ == "__main__":
    main()
